CREATE TYPE "WithdrawalStatus_new" AS ENUM ('PENDING','APPROVED','PROCESSING','SUCCESSFUL','REJECTED','FAILED','REVERSED','REFUND_PENDING','REFUNDED','REFUND_FAILED');
ALTER TABLE "Withdrawal" ALTER COLUMN "status" DROP DEFAULT;
ALTER TABLE "Withdrawal" ALTER COLUMN "status" TYPE "WithdrawalStatus_new" USING (CASE "status"::text WHEN 'PAID' THEN 'SUCCESSFUL' ELSE "status"::text END)::"WithdrawalStatus_new";
DROP TYPE "WithdrawalStatus";
ALTER TYPE "WithdrawalStatus_new" RENAME TO "WithdrawalStatus";
ALTER TABLE "Withdrawal" ALTER COLUMN "status" SET DEFAULT 'PENDING';
CREATE TYPE "WithdrawalRefundStatus" AS ENUM ('PENDING','REFUNDED','FAILED');
ALTER TABLE "Withdrawal" ADD COLUMN "fee" DECIMAL(18,2) NOT NULL DEFAULT 0, ADD COLUMN "bankCode" TEXT, ADD COLUMN "accountVerified" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "refundLedgerEntryId" TEXT, ADD COLUMN "providerReference" TEXT, ADD COLUMN "verificationEvidence" TEXT, ADD COLUMN "approvedBy" TEXT, ADD COLUMN "approvedAt" TIMESTAMP(3), ADD COLUMN "processingAt" TIMESTAMP(3), ADD COLUMN "settledAt" TIMESTAMP(3), ADD COLUMN "refundedAmount" DECIMAL(18,2) NOT NULL DEFAULT 0, ADD COLUMN "refundStatus" "WithdrawalRefundStatus", ADD COLUMN "refundedAt" TIMESTAMP(3);
CREATE UNIQUE INDEX "Withdrawal_ledgerEntryId_key" ON "Withdrawal"("ledgerEntryId");
CREATE UNIQUE INDEX "Withdrawal_refundLedgerEntryId_key" ON "Withdrawal"("refundLedgerEntryId");
CREATE TABLE "WithdrawalEvent" ("id" TEXT NOT NULL,"withdrawalId" TEXT NOT NULL,"action" TEXT NOT NULL,"fromStatus" "WithdrawalStatus","toStatus" "WithdrawalStatus" NOT NULL,"reason" TEXT,"actorId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WithdrawalEvent_pkey" PRIMARY KEY ("id"));
CREATE INDEX "WithdrawalEvent_withdrawalId_createdAt_idx" ON "WithdrawalEvent"("withdrawalId","createdAt");
ALTER TABLE "WithdrawalEvent" ADD CONSTRAINT "WithdrawalEvent_withdrawalId_fkey" FOREIGN KEY ("withdrawalId") REFERENCES "Withdrawal"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "WithdrawalPayoutAttempt" ("id" TEXT NOT NULL,"withdrawalId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"status" TEXT NOT NULL,"providerReference" TEXT,"failureReason" TEXT,"evidence" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WithdrawalPayoutAttempt_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WithdrawalPayoutAttempt_idempotencyKey_key" ON "WithdrawalPayoutAttempt"("idempotencyKey");
CREATE INDEX "WithdrawalPayoutAttempt_withdrawalId_createdAt_idx" ON "WithdrawalPayoutAttempt"("withdrawalId","createdAt");
ALTER TABLE "WithdrawalPayoutAttempt" ADD CONSTRAINT "WithdrawalPayoutAttempt_withdrawalId_fkey" FOREIGN KEY ("withdrawalId") REFERENCES "Withdrawal"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "WithdrawalRefund" ("id" TEXT NOT NULL,"withdrawalId" TEXT NOT NULL,"ledgerEntryId" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"status" "WithdrawalRefundStatus" NOT NULL DEFAULT 'PENDING',"reason" TEXT NOT NULL,"actorId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "WithdrawalRefund_pkey" PRIMARY KEY ("id"));
