ALTER TABLE "WithdrawalRefund" ADD CONSTRAINT "WithdrawalRefund_withdrawalId_fkey" FOREIGN KEY ("withdrawalId") REFERENCES "Withdrawal"("id") ON DELETE CASCADE ON UPDATE CASCADE;
